<script setup lang="ts">
import { ArrowRight, BookOpenText, Boxes, FileText, FlaskConical } from 'lucide-vue-next'
import StatusDot from '@/components/ui/StatusDot.vue'
import AppBadge from '@/components/ui/AppBadge.vue'
import { paperStatusMeta } from '@/modules/papers/data'
import { useWorkspaceStore } from '@/stores/workspace'
import { useSiteContentStore } from '@/stores/siteContent'
import { computed, onMounted, ref } from 'vue'
import { http } from '@/services/http'
import { locale } from '@/i18n'
import { storeToRefs } from 'pinia'
const workspace = useWorkspaceStore()
const siteContent = useSiteContentStore()
const papers = computed(() => workspace.apiLoaded ? workspace.papers : [])
const servers = computed(() => workspace.apiLoaded ? workspace.servers.filter(s => s.provider !== 'mock' && s.enabled !== false) : [])
const stats = ref<{research:{total:number;active:number};papers:{total:number;toRead:number};documents:{total:number;private:number};servers:{total:number;online:number;gpus:number}} | null>(null)
onMounted(async () => { try { stats.value = (await http.get<typeof stats.value>('/overview/')).data } catch { /* Render unavailable counts, never demo numbers. */ } })
const documents = computed(() => (workspace.apiLoaded ? workspace.documents : []).filter(d => !d.trashedAt).sort((a,b) => b.updatedAt.localeCompare(a.updatedAt)))
const currentResearch = computed(() => siteContent.apiLoaded ? siteContent.localized.currentResearch : [])
const activeResearchCount = computed(() => currentResearch.value.filter(item => item.status.toLowerCase().includes('active')).length)
const onlineServerCount = computed(() => servers.value.filter(server => server.status !== 'offline').length)
const gpuCount = computed(() => servers.value.reduce((count, server) => count + server.gpus.length, 0))
const todayLabel = computed(() => new Intl.DateTimeFormat(locale.value === 'zh' ? 'zh-CN' : 'en-US', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date()).toUpperCase())
</script>
<template><div><header class="overview-greeting"><div><p>{{ todayLabel }}</p><h1>{{ $t('Welcome back') + ', ' + siteContent.localized.name }}</h1><span>{{ $t("Here’s the current state of your research workspace.") }}</span></div><div class="overview-focus"><span><i /> {{ $t("Current focus") }}</span><strong>{{ currentResearch[0]?.title || $t('No current research set') }}</strong><RouterLink to="/dashboard/content">{{ $t("Edit public site") }} <ArrowRight :size="13" /></RouterLink></div></header><section class="stat-row"><article><FlaskConical :size="18" /><div><span>{{ $t("Research") }}</span><strong>{{ stats?.research.active ?? '—' }} <small>{{ $t("active") }}</small></strong><p>{{ stats?.research.total ?? '—' }} {{ $t("tracked questions") }}</p></div></article><article><BookOpenText :size="18" /><div><span>{{ $t("Recommended papers") }}</span><strong>{{ stats?.papers.total ?? '—' }} <small>{{ $t("collected") }}</small></strong><p>{{ stats?.papers.toRead ?? '—' }} {{ $t("to read") }}</p></div></article><article><Boxes :size="18" /><div><span>{{ $t("Servers") }}</span><strong>{{ stats?.servers.online ?? '—' }} / {{ stats?.servers.total ?? '—' }} <small>{{ $t("online") }}</small></strong><p>{{ stats?.servers.gpus ?? '—' }} {{ $t("GPUs") }}</p></div></article><article><FileText :size="18" /><div><span>{{ $t("Documents") }}</span><strong>{{ stats?.documents.total ?? '—' }} <small>{{ $t("total") }}</small></strong><p>{{ stats?.documents.private ?? '—' }} {{ $t("private") }}</p></div></article></section><div class="overview-grid"><section class="overview-panel current-research-panel"><header><div><p>{{ $t("Research") }}</p><h2>{{ $t("Current research") }}</h2></div><RouterLink to="/dashboard/content">{{ $t("Manage") }} <ArrowRight :size="14" /></RouterLink></header><div class="overview-research-list"><article v-for="item in currentResearch" :key="item.id"><div><h3>{{ item.title }}</h3><p>{{ item.status }} · {{ item.updated }}</p></div><span>{{ item.status }}</span></article><p v-if="!currentResearch.length" class="empty-hint">{{ $t("No current research questions yet.") }}</p></div></section><section class="overview-panel server-status-panel"><header><div><p>{{ $t("Infrastructure") }}</p><h2>{{ $t("Server status") }}</h2></div><RouterLink to="/dashboard/servers">{{ $t("Fleet") }} <ArrowRight :size="14" /></RouterLink></header><div class="compact-server-list"><article v-for="server in servers.slice(0,3)" :key="server.id"><StatusDot :status="server.status" /><div><h3>{{ server.name }}</h3><p>{{ server.status === 'offline' ? `Last seen ${server.lastSeen || $t('never')}` : `${server.cpu}% CPU · ${server.memory.used} GB RAM` }}</p></div><span v-if="server.gpus.length && server.status !== 'offline'">{{ server.gpus[0].utilization }}{{ $t("% GPU") }}</span><span v-else>{{ $t(server.status) }}</span></article><p v-if="!servers.length" class="empty-hint">{{ $t("No servers in the inventory.") }}</p></div></section><section class="overview-panel papers-panel"><header><div><p>{{ $t("Literature") }}</p><h2>{{ $t("Recommended papers") }}</h2></div><RouterLink to="/dashboard/papers">{{ $t("All papers") }} <ArrowRight :size="14" /></RouterLink></header><div class="compact-paper-list"><article v-for="paper in papers.slice(0,4)" :key="paper.id"><AppBadge :tone="paperStatusMeta[paper.status].tone">{{ $t(paperStatusMeta[paper.status].label) }}</AppBadge><div><h3>{{ paper.title }}</h3><p>{{ paper.venue }} {{ paper.year }} · {{ paper.topic }}</p></div><time>{{ paper.recommendedAt.replace(', 2026','') }}</time></article><p v-if="!papers.length" class="empty-hint">{{ $t("No recommended papers yet.") }}</p></div></section><section class="overview-panel documents-panel"><header><div><p>{{ $t("Writing") }}</p><h2>{{ $t("Documents") }}</h2></div><RouterLink to="/dashboard/docs">{{ $t("All docs") }} <ArrowRight :size="14" /></RouterLink></header><div class="compact-doc-list"><article v-for="doc in documents.slice(0, 3)" :key="doc.id"><FileText :size="16" /><div><h3><RouterLink :to="{ path: '/dashboard/docs', query: { note: doc.id } }">{{ doc.title }}</RouterLink></h3><p>{{ doc.updatedAt }} · {{ $t(doc.visibility) }}</p></div></article><p v-if="!documents.length">{{ $t("No active documents yet.") }}</p></div></section></div></div></template>
